Use ASP.NET Core's built-in **`WebApplicationFactory<T>`** from `Microsoft.AspNetCore.Mvc.Testing`. It hosts your app in-memory — no ports, no real server.

### Setup

```bash
dotnet add tests/MyTests.csproj package Microsoft.AspNetCore.Mvc.Testing
```

### Example test class

```csharp
public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.True(body.TryGetProperty("result", out var result));
        Assert.True(result.TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        // Initialize first (required by MCP)
        await InitializeSession();

        var request = new { jsonrpc = "2.0", id = 2, method = "tools/list" };
        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }

    private async Task InitializeSession()
    {
        var init = new
        {
            jsonrpc = "2.0", id = 0, method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test", version = "1.0" }
            }
        };
        await _client.PostAsJsonAsync("/mcp", init);
    }
}
```

### Key points

- **`WebApplicationFactory<Program>`** boots your real DI container, middleware, and routing in-process — requests never hit the network.
- If your server uses **Streamable HTTP** (single `POST /mcp` endpoint), the above pattern works directly.
- If using **SSE transport**, use `factory.CreateClient()` for the `POST` endpoint and `factory.Server.CreateHandler()` with `HttpMessageInvoker` to stream SSE responses.
- Override services for testing (e.g., mock databases) via `factory.WithWebHostBuilder(b => b.ConfigureServices(...))`.
- Make sure `Program` is accessible — add `[assembly: InternalsVisibleTo("YourTestProject")]` or a partial class if needed.
